CREATE OR REPLACE VIEW `v_files` AS SELECT `m`.`id` AS `material_id`, `s`.`code` AS `subject_code`, `s`.`name` AS `subject_name`, `c`.`name` AS `class_name`, `g`.`name` AS `group_name`, `t`.`id` AS `topic_id`, `t`.`title` AS `topic_title`, `m`.`original_filename` AS `filename`, `m`.`mime_type` AS `mime_type`, `m`.`size_bytes` AS `size_bytes`, `m`.`preview_kind` AS `preview_kind`, `m`.`status` AS `status`, `u`.`display_name` AS `uploader`, `m`.`created_at` AS `created_at`, `s`.`id` AS `subject_id`, `t`.`class_id` AS `class_id`, `t`.`group_id` AS `group_id`, `m`.`uploader_id` AS `uploader_id` FROM `materials` `m` JOIN `topics` `t` ON `t`.`id` = `m`.`topic_id` AND `t`.`deleted_at` IS NULL JOIN `subjects` `s` ON `s`.`id` = `t`.`subject_id` LEFT JOIN `classes` `c` ON `c`.`id` = `t`.`class_id` LEFT JOIN `class_groups` `g` ON `g`.`id` = `t`.`group_id` LEFT JOIN `users` `u` ON `u`.`id` = `m`.`uploader_id` WHERE `m`.`deleted_at` IS NULL;
